// AJAX REQUEST CHECK
$ajax_request = isset($this->request->server['HTTP_X_REQUESTED_WITH']) && !empty($this->request->server['HTTP_X_REQUESTED_WITH']) && strtolower($this->request->server['HTTP_X_REQUESTED_WITH']) == 'xmlhttprequest';
if ($ajax_request) {
	$json = array();

	$json['error'] = 1;
	$json['error_type'] = "maintenance";

	$this->response->addHeader('Content-Type: application/json');
	$this->response->setOutput(json_encode($json));

	return;
}

$data['placeholder_img'] = $this->model_tool_image->resize('placeholder.png', $this->config->get($this->config->get('config_theme') . '_image_product_width'), $this->config->get($this->config->get('config_theme') . '_image_product_height'));
$this->load->helper('es');
$data['es_status'] = $this->config->get('es_status') && in_array($this->config->get('config_store_id'), bdecode($this->config->get('es_as')));
if ($data['es_status']) {
	$this->document->addScript('catalog/view/javascript/es/custom.min.js');
	$pages = 0;
	$end_page = isset($page) ? $page : 1;
	if (!isset($this->request->get['page']) && isset($this->request->get['pages'])) {
		if (strpos($this->request->get['pages'], "-")) {
			$span = explode("-", $this->request->get['pages']);
			if (count($span) == 2) {
				list($page, $end_page) = $span;
			}
		} else {
			$page = 1;
			$end_page = $this->request->get['pages'];
		}
		if ((int)$end_page > (int)$page) {
			if (($end_page - $page + 1) * $limit > (int)$this->config->get('es_max_items_per_load')) {
				$end_page = floor(((int)$this->config->get('es_max_items_per_load') / $limit) - 1 + $page);
			}
			$pages = $end_page - $page;
			$limit = ($end_page - $page + 1) * $limit;
		} else {
			$page = 1;
		}
	}
}

$this->load->helper('es');
$data['es_status'] = $this->config->get('es_status') && in_array($this->config->get('config_store_id'), bdecode($this->config->get('es_as')));
if ($data['es_status']) {
	$url = '';

	if (isset($this->request->get['filter'])) {
		$url .= '&filter=' . $this->request->get['filter'];
	}

	if (isset($this->request->get['sort'])) {
		$url .= '&sort=' . $this->request->get['sort'];
	}

	if (isset($this->request->get['order'])) {
		$url .= '&order=' . $this->request->get['order'];
	}

	if (isset($this->request->get['limit'])) {
		$url .= '&limit=' . $this->request->get['limit'];
	}

	$page = ($page > 0) ? $page : 1;
	$current_page = (($page + $pages) * $_limit > $product_total) ? ceil($product_total / $_limit) : $page + $pages;
	$data['text_more_results'] = $this->language->get('text_more_results');
	$data['text_showing'] = $this->language->get('text_showing');
	$data['text_loading'] = $this->language->get('text_loading');
	$data['bottom_pixels'] = $this->config->get('es_bottom_pixels');
	$data['use_fade_in'] = $this->config->get('es_use_fade_in');
	$data['start_page'] = $page;
	$data['current_page'] = $current_page;
	//$data['next_page_link'] = html_entity_decode($this->url->link('product/category/next_page', 'path=' . $this->request->get['path'] . $url . '&page=')); // SEO URLs do not work here, because the URL library does not create a valid link
	$data['next_page_link'] = html_entity_decode('index.php?route=product/category/next_page&path=' . $this->request->get['path'] . $url . '&page=');
	$data['total_products'] = $product_total;
	$data['page_limit'] = $_limit;
	$data['use_more'] = $this->config->get('es_use_more');
	$data['use_more_after'] = $this->config->get('es_use_more_after');
	$data['auto_load_counter'] = ($current_page - 1) % ((int)$this->config->get('es_use_more_after') + 1);
	$data['use_back_top'] = $this->config->get('es_use_back_to_top');
	$data['use_sticky_footer'] = $this->config->get('es_use_sticky_footer');
}

public function next_page() {
	$this->load->helper('es');

	$this->load->language('product/category');

	$this->load->model('catalog/category');

	$this->load->model('catalog/product');

	$this->load->model('tool/image');

	if (isset($this->request->get['filter'])) {
		$filter = $this->request->get['filter'];
	} else {
		$filter = '';
	}

	if (isset($this->request->get['sort'])) {
		$sort = $this->request->get['sort'];
	} else {
		$sort = 'p2c.sort_order';
	}

	if (isset($this->request->get['order'])) {
		$order = $this->request->get['order'];
	} else {
		$order = 'ASC';
	}

	if (isset($this->request->get['page'])) {
		$page = (int)$this->request->get['page'];
	} else {
		$page = 1;
	}

	if (isset($this->request->get['limit'])) {
		$limit = (int)$this->request->get['limit'];
	} else {
		$limit = $this->config->get($this->config->get('config_theme') . '_product_limit');
	}

	if (isset($this->request->get['path'])) {
		$path = '';

		$parts = explode('_', (string)$this->request->get['path']);

		$path_cats=$parts;

		$category_id = (int)array_pop($parts);
	} else {
		$category_id = 0;
	}

	$category_info = $this->model_catalog_category->getCategory($category_id);

	if ($category_info) {
		$url = '';

		if (isset($this->request->get['filter'])) {
			$url .= '&filter=' . $this->request->get['filter'];
		}

		if (isset($this->request->get['sort'])) {
			$url .= '&sort=' . $this->request->get['sort'];
		}

		if (isset($this->request->get['order'])) {
			$url .= '&order=' . $this->request->get['order'];
		}

		if (isset($this->request->get['limit'])) {
			$url .= '&limit=' . $this->request->get['limit'];
		}

		$data['text_tax'] = $this->language->get('text_tax');

		$data['button_cart'] = $this->language->get('button_cart');
		$data['button_wishlist'] = $this->language->get('button_wishlist');
		$data['button_compare'] = $this->language->get('button_compare');

		$data['cit_status'] = $this->config->get('cit_status');

		$data['placeholder_img'] = $this->model_tool_image->resize('placeholder.png', $this->config->get($this->config->get('config_theme') . '_image_product_width'), $this->config->get($this->config->get('config_theme') . '_image_product_height'));

		$data['products'] = array();

		if(count($path_cats)==2){
			$mc_parent_id=$path_cats[0];
			$mc_cat_id=$path_cats[1];
		} else {
			$mc_parent_id=0;
			$mc_cat_id=$path_cats[0];
		}

		$multicategory=$this->db->query("SELECT * from ".DB_PREFIX."category_multiparent where parent_id=".$mc_parent_id." and category_id=".$mc_cat_id)->row;

		$filter_data = array(
			'filter_category_id' => $multicategory['id'],
			'filter_filter'      => $filter,
			'sort'               => $sort,
			'order'              => $order,
			'start'              => ($page - 1) * $limit,
			'limit'              => $limit
		);

		$results = $this->model_catalog_product->getProducts($filter_data);

		foreach ($results as $result) {
			if ($result['image']) {
				$image = $this->model_tool_image->resize($result['image'], $this->config->get($this->config->get('config_theme') . '_image_product_width'), $this->config->get($this->config->get('config_theme') . '_image_product_height'));
			} else {
				$image = $data['placeholder_img'];
			}

			if ($this->customer->isLogged() || !$this->config->get('config_customer_price')) {
				$price = $this->currency->format($this->tax->calculate($result['price'], $result['tax_class_id'], $this->config->get('config_tax')), $this->session->data['currency']);
			} else {
				$price = false;
			}

			if ((float)$result['special']) {
				$special = $this->currency->format($this->tax->calculate($result['special'], $result['tax_class_id'], $this->config->get('config_tax')), $this->session->data['currency']);
			} else {
				$special = false;
			}

			if ($this->config->get('config_tax')) {
				$tax = $this->currency->format((float)$result['special'] ? $result['special'] : $result['price'], $this->session->data['currency']);
			} else {
				$tax = false;
			}

			if ($this->config->get('config_review_status')) {
				$rating = (int)$result['rating'];
			} else {
				$rating = false;
			}

			$data['products'][] = array(
				'product_id'  => $result['product_id'],
				'thumb'       => $image,
				'image_alt'   => isset($result['alt_text']) ? $result['alt_text'] : '',
				'image_title' => isset($result['title_text']) ? $result['title_text'] : '',
				'name'        => $result['name'],
				'description' => utf8_substr(strip_tags(html_entity_decode($result['description'], ENT_QUOTES, 'UTF-8')), 0, $this->config->get($this->config->get('config_theme') . '_product_description_length')) . '..',
				'price'       => $price,
				'special'     => $special,
				'tax'         => $tax,
				'minimum'     => (isset($result['minimum']) && $result['minimum'] > 0) ? $result['minimum'] : 1,
				'rating'      => $result['rating'],
				'href'        => $this->url->link('product/product', 'product_id=' . $result['product_id'] . $url)
			);
		}

		$template = 'product/category_products';

		$response = array("success" => 1, "data" => $this->load->view($template, $data));

		$this->response->addHeader('Content-Type: application/json');
		$this->response->setOutput(json_enc($response, JSON_UNESCAPED_SLASHES));
	}
}

